import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBebas = makeLoadFont('BebasNeue');
const loadInter = makeLoadFont('Inter');

// Module-level font loading ensures fonts are ready before frame 0
const { fontFamily: bebasFamily } = loadBebas();
const { fontFamily: interFamily } = loadInter();



export type VlogNameTagProps = Record<string, any>;

const VlogNameTag: React.FC<VlogNameTagProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 6,
  name = "MR DQ",
  subtitle = "HIGH ROLLER",
  tagColor = "#1a1a1a",
  accentColor = "#D4AF37", // Casino Gold
  textColor = "#FFFFFF",
  position = "bottom-left",
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Safety logic for transparent background
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  const isLeft = position === "bottom-left";
  const durationInFrames = durationInSeconds * fps;
  const exitStartFrame = durationInFrames - 30;

  // --- ANIMATION LOGIC ---

  // 1. Container Slide/Reveal (Horizontal Expand)
  const containerProgress = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 120, mass: 1 },
  });
  const clipRight = isLeft ? interpolate(containerProgress, [0, 1], [100, 0]) : 0;
  const clipLeft = isLeft ? 0 : interpolate(containerProgress, [0, 1], [100, 0]);

  // 2. Slot Reel Name Roll (Mechanical Clunk)
  const nameRollSpring = spring({
    frame: frame - 8,
    fps,
    config: { damping: 10, mass: 1.2, stiffness: 150 },
  });
  const nameY = interpolate(nameRollSpring, [0, 1], [100, 0]);

  // 3. Subtitle Slide & Fade
  const subtitleOp = interpolate(frame, [15, 30], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const subtitleX = interpolate(
    spring({ frame: frame - 15, fps, config: { damping: 12 } }),
    [0, 1],
    [isLeft ? -20 : 20, 0]
  );

  // 4. Glare Sweep (Casino Shine)
  const glareProgress = interpolate(frame, [45, 75], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const glareLeft = interpolate(glareProgress, [0, 1], [-100, 200]);

  // 5. Exit Animation
  const exitOpacity = interpolate(
    frame,
    [exitStartFrame, durationInFrames],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const exitTranslateY = interpolate(
    frame,
    [exitStartFrame, durationInFrames],
    [0, 50],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Responsive scaling calculations
  const safeZone = width * 0.05;
  const padX = width * 0.03;
  const padY = width * 0.015;
  const nameFontSize = width * 0.05;
  const subFontSize = width * 0.013;
  const borderThickness = Math.max(4, width * 0.005);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          position: "absolute",
          bottom: safeZone,
          left: isLeft ? safeZone : "auto",
          right: !isLeft ? safeZone : "auto",
          display: "flex",
          flexDirection: "column",
          alignItems: isLeft ? "flex-start" : "flex-end",
          opacity: exitOpacity,
          transform: `translateY(${exitTranslateY}px)`,
          transition: "none",
        }}
      >
        {/* Name Tag Main Container */}
        <div
          style={{
            backgroundColor: tagColor,
            borderLeft: isLeft ? `${borderThickness}px solid ${accentColor}` : "none",
            borderRight: !isLeft ? `${borderThickness}px solid ${accentColor}` : "none",
            padding: `${padY}px ${padX}px`,
            position: "relative",
            overflow: "hidden",
            clipPath: `inset(0% ${clipRight}% 0% ${clipLeft}%)`,
            boxShadow: "0 20px 40px rgba(0,0,0,0.6)",
            transition: "none",
            borderRadius: isLeft ? "0 8px 8px 0" : "8px 0 0 8px",
          }}
        >
          {/* Inner Slot Glass Shadow (3D depth effect) */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              boxShadow:
                "inset 0px 15px 20px -15px rgba(0,0,0,0.9), inset 0px -15px 20px -15px rgba(0,0,0,0.9)",
              pointerEvents: "none",
              zIndex: 2,
            }}
          />

          {/* Glare Effect element */}
          <div
            style={{
              position: "absolute",
              top: 0,
              bottom: 0,
              left: `${glareLeft}%`,
              width: "30%",
              background:
                "linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.4), transparent)",
              transform: "skewX(-25deg)",
              zIndex: 3,
              transition: "none",
            }}
          />

          {/* SLOT REEL TEXT CONTAINER */}
          <div
            style={{
              overflow: "hidden",
              paddingTop: "4px",
              paddingBottom: "4px",
              display: "flex",
              justifyContent: isLeft ? "flex-start" : "flex-end",
            }}
          >
            <div
              style={{
                fontFamily: bebasFamily,
                fontSize: `${nameFontSize}px`,
                color: textColor,
                lineHeight: 1,
                transform: `translateY(${nameY}%)`,
                transition: "none",
                textShadow: "0px 4px 10px rgba(0,0,0,0.5)",
              }}
            >
              {name}
            </div>
          </div>

          {/* SUBTITLE */}
          <div
            style={{
              overflow: "hidden",
              display: "flex",
              justifyContent: isLeft ? "flex-start" : "flex-end",
            }}
          >
            <div
              style={{
                fontFamily: interFamily,
                fontSize: `${subFontSize}px`,
                color: accentColor,
                fontWeight: 700,
                letterSpacing: "0.2em",
                textTransform: "uppercase",
                marginTop: "4px",
                opacity: subtitleOp,
                transform: `translateX(${subtitleX}px)`,
                transition: "none",
              }}
            >
              {subtitle}
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default VlogNameTag;